WITH src AS (SELECT *, CEIL(budget) AS budget_whole FROM departments WHERE location <> 'Berlin' AND budget IS NOT NULL), budget_bucket_summary AS (SELECT CASE WHEN budget >= 4470000 THEN 'high' WHEN budget >= 679000 THEN 'mid' ELSE 'low' END AS budget_bucket, MAX(budget) AS max_budget, MAX(budget_whole) AS max_budget_whole FROM src GROUP BY CASE WHEN budget >= 4470000 THEN 'high' WHEN budget >= 679000 THEN 'mid' ELSE 'low' END) SELECT * FROM budget_bucket_summary;
